def fill_public_ids(apps, schema_editor):
    """Проставляет public_id всем существующим пользователям."""
    User = apps.get_model('manga', 'User')
    for user in User.objects.filter(public_id__isnull=True).iterator():
        while True:
            pid = str(secrets.randbelow(90000000) + 10000000)
            if not User.objects.filter(public_id=pid).exists():
                break
        user.public_id = pid
        user.save(update_fields=['public_id'])


